var t=[{title:`Wat meetelt`,text:`Actief herstel is beweging die je bewust rustiger houdt dan je normale training. Een comfortabele wandeling, een ontspannen zwempartij, rustig trappen of een korte mobiliteitssessie kan je beter laten voelen en de gewoonte van bewegen in stand houden. Je hoeft niet te zweten, uitgeput te raken of een hoge hartslagzone te bereiken.`},{title:`Hoe rustig het moet zijn`,text:`Je moet zonder moeite kunnen praten en niet vermoeider eindigen dan je begon. Branden je benen, voeg je zware intervallen toe of kom je dicht bij spierfalen, dan is dat extra training. Als vermoeidheid, klachten of een druk schema zich opstapelen, kan volledige rust de betere keuze zijn. Hersteldagen zijn optioneel, en actief herstel vervangt rust niet.`},{title:`Voorbeeld`,text:`Na een zware beentraining kun je 15–25 minuten wandelen en wat ontspannen heup- en enkelbewegingen doen. Controleer de volgende dag of je normale prestatie terugkomt. Rekken of foamrollen kan prettig voelen, maar je hebt geen van beide nodig om spierpijn te laten verdwijnen, en geen van beide garandeert sneller herstel.`},{title:`Wat het bewijs niet laat zien`,text:`Onderzoek heeft niet aangetoond dat elke vorm van actief herstel het lichamelijk herstel versnelt. Spierpijn die een tijdje afneemt, bewijst niet dat je weefsels hersteld zijn. Gebruik beweging nooit om door ernstige of verergerende pijn heen te duwen.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: wandelen voor je gezondheid`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};